SELECT F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PARTSUPP_PS__SUPPKEY AS PROV_PARTSUPP_PS__SUPPKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY
